import Config

# Note we also include the path to a cache manifest
# containing the digested version of static files. This
# manifest is generated by the `mix assets.deploy` task,
# which you should run after static files are built and
# before starting your production server.
config :couriercms, CourierCMSWeb.Endpoint,
  cache_static_manifest: "priv/static/cache_manifest.json"

# Server terminates TLS itself or behind a trusted proxy. Local is deliberately
# loopback-only HTTP; forcing HTTPS there would redirect to a nonexistent local
# certificate endpoint. `:force_ssl` must be selected at compile time.
if System.get_env("COURIERCMS_RELEASE_PROFILE", "server") == "server" do
  config :couriercms, CourierCMSWeb.Endpoint,
    force_ssl: [
      rewrite_on: [:x_forwarded_proto],
      exclude: [
        paths: ["/health/live", "/health/ready"]
      ]
    ]
else
  config :couriercms, CourierCMSWeb.Endpoint, force_ssl: false
end

# Do not print debug messages in production
config :logger, level: :info

config :logger, :default_formatter,
  format: {CourierCMS.Logging.JSONFormatter, :format},
  metadata: :all

# Runtime production configuration, including reading
# of environment variables, is done on config/runtime.exs.
